    50	    public CheckoutSummary calculateSummary(CheckoutRequest request, Connection conn) throws SQLException {
    51	        validateRequest(request, conn);
    52	
    53	        Set<String> skus = new HashSet<>();
    54	        for (OrderItem item : request.getItems()) {
    55	            skus.add(item.getSku());
    56	        }
    57	        Map<String, Product> productMap = productRepository.findBySkus(skus);
    58	
    59	        BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems(), productMap);
    60	        productsSubtotal = MoneyUtils.roundMoney(productsSubtotal);
    61	
    62	        boolean isFirstPurchase = conn == null || !orderRepository.hasCompletedOrders(request.getCustomer().getCpf(), conn);
    63	
    64	        BigDecimal couponDiscount = BigDecimal.ZERO;
    65	        boolean hasCoupon = request.getCoupon() != null && !request.getCoupon().isEmpty();
    66	        if (hasCoupon) {
    67	            CouponStrategy coupon = couponService.getCoupon(request.getCoupon());
    68	            if (!coupon.isApplicable(request, productMap, isFirstPurchase)) {
    69	                throw new ApiException("COUPON_NOT_APPLICABLE", 422);
    70	            }
    71	
    72	            ShippingResult shippingForCoupon = shippingCalculator.calculate(request, productMap);
    73	            BigDecimal preliminaryShipping = clubBenefitsCalculator.hasFreeShipping(request.getClubTier(), request.getShippingMethod())
    74	                ? BigDecimal.ZERO
    75	                : shippingForCoupon.getCost();
    76	
    77	            couponDiscount = coupon.calculateDiscount(productsSubtotal, preliminaryShipping, request.getItems(), productMap);
    78	            couponDiscount = couponService.applyCap(couponDiscount, productsSubtotal);
    79	        }
    80	
    81	        ShippingResult shippingResult = shippingCalculator.calculate(request, productMap);
    82	        BigDecimal shippingCost = clubBenefitsCalculator.hasFreeShipping(request.getClubTier(), request.getShippingMethod())
    83	            ? BigDecimal.ZERO
    84	            : shippingResult.getCost();
    85	        int deliveryDays = shippingResult.getDeliveryDays();
    86	
    87	        BigDecimal insurance = insuranceCalculator.calculate(productsSubtotal, request.getRegion());
    88	
    89	        BigDecimal orderTotal = productsSubtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
    90	
    91	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
    92	        BigDecimal paymentAdjustment = paymentAdjustmentCalculator.calculate(orderTotal, request.getPaymentMethod(), installments, hasCoupon);
    93	
    94	        BigDecimal finalTotal = orderTotal.add(paymentAdjustment);
    95	        BigDecimal installmentAmount = paymentAdjustmentCalculator.calculateInstallmentAmount(finalTotal, installments);
    96	
    97	        BigDecimal nextPurchaseCredit = clubBenefitsCalculator.calculateCredit(productsSubtotal, request.getClubTier());
    98	        boolean gift = clubBenefitsCalculator.hasGift(request.getClubTier(), productsSubtotal);
    99	
   100	        CheckoutSummary summary = new CheckoutSummary();
   101	        summary.setProductsSubtotal(productsSubtotal);
   102	        summary.setCouponDiscount(couponDiscount);
   103	        summary.setShippingCost(shippingCost);
   104	        summary.setDeliveryDays(deliveryDays);
   105	        summary.setInsurance(insurance);
   106	        summary.setPaymentAdjustment(paymentAdjustment);
   107	        summary.setFinalTotal(finalTotal);
   108	        summary.setInstallments(installments);
   109	        summary.setInstallmentAmount(installmentAmount);
   110	        summary.setNextPurchaseCredit(nextPurchaseCredit);
   111	        summary.setGift(gift);
   112	
   113	        return summary;
   114	    }
