     9	public class Buy3Pay2Coupon implements CouponStrategy {
    10	    @Override
    11	    public String getCode() {
    12	        return "BUY3PAY2";
    13	    }
    14	
    15	    @Override
    16	    public boolean isApplicable(CheckoutRequest request, Map<String, Product> productMap, boolean isFirstPurchase) {
    17	        return true;
    18	    }
    19	
    20	    @Override
    21	    public BigDecimal calculateDiscount(BigDecimal productsSubtotal, BigDecimal shippingCost, List<OrderItem> items, Map<String, Product> productMap) {
    22	        BigDecimal totalDiscount = BigDecimal.ZERO;
    23	        for (OrderItem item : items) {
    24	            if (item.getQuantity() >= 3) {
    25	                Product product = productMap.get(item.getSku());
    26	                int freeItems = item.getQuantity() / 3;
    27	                BigDecimal discount = product.getPrice().multiply(new BigDecimal(freeItems));
    28	                totalDiscount = totalDiscount.add(discount);
    29	            }
    30	        }
    31	        return MoneyUtils.roundMoney(totalDiscount);
    32	    }
