     8	public class CouponService {
     9	    private final Map<String, CouponStrategy> coupons = new HashMap<>();
    10	
    11	    public CouponService() {
    12	        List<CouponStrategy> strategies = List.of(
    13	            new Welcome10Coupon(),
    14	            new Minus50Coupon(),
    15	            new FreeShippingCoupon(),
    16	            new Buy3Pay2Coupon()
    17	        );
    18	        for (CouponStrategy strategy : strategies) {
    19	            coupons.put(strategy.getCode(), strategy);
    20	        }
    21	    }
    22	
    23	    public boolean exists(String couponCode) {
    24	        return coupons.containsKey(couponCode);
    25	    }
    26	
    27	    public CouponStrategy getCoupon(String couponCode) {
    28	        return coupons.get(couponCode);
    29	    }
    30	
    31	    public BigDecimal applyCap(BigDecimal discount, BigDecimal productsSubtotal) {
    32	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"));
    33	        if (discount.compareTo(maxDiscount) > 0) {
    34	            return maxDiscount.setScale(2, java.math.RoundingMode.HALF_EVEN);
    35	        }
    36	        return discount;
    37	    }
    38	}
