    10	public class ShippingCalculator {
    11	    private final TransLogClient transLogClient;
    12	
    13	    public ShippingCalculator(TransLogClient transLogClient) {
    14	        this.transLogClient = transLogClient;
    15	    }
    16	
    17	    public ShippingResult calculate(CheckoutRequest request, Map<String, Product> productMap) {
    18	        BigDecimal totalWeight = calculateTotalWeight(request.getItems(), productMap);
    19	
    20	        return switch (request.getShippingMethod()) {
    21	            case STORE_PICKUP -> new ShippingResult(BigDecimal.ZERO, 1);
    22	            case COURIER -> {
    23	                if (totalWeight.compareTo(new BigDecimal("5.0")) > 0) {
    24	                    throw new ApiException("SHIPPING_METHOD_UNAVAILABLE", 422);
    25	                }
    26	                yield new ShippingResult(new BigDecimal("18.00"), 0);
    27	            }
    28	            case ECONOMY, EXPRESS -> {
    29	                try {
    30	                    ShippingResult result = transLogClient.quote(
    31	                        request.getZipCode(),
    32	                        totalWeight,
    33	                        request.getShippingMethod(),
    34	                        request.getRegion()
    35	                    );
    36	                    if (result == null) {
    37	                        throw new ApiException("SHIPPING_METHOD_UNAVAILABLE", 422);
    38	                    }
    39	                    yield result;
    40	                } catch (RuntimeException e) {
    41	                    if (e.getMessage().equals("CARRIER_UNAVAILABLE")) {
    42	                        throw new ApiException("CARRIER_UNAVAILABLE", 503);
    43	                    }
    44	                    throw e;
    45	                }
    46	            }
    47	        };
    48	    }
