     1	package com.loja.service;
     2	
     3	import com.loja.domain.*;
     4	import com.loja.repository.*;
     5	import com.loja.util.ApiException;
     6	
     7	import java.sql.Connection;
     8	import java.sql.SQLException;
     9	import java.time.Duration;
    10	import java.time.Instant;
    11	import java.util.*;
    12	
    13	public class OrderService {
    14	    private final Database database;
    15	    private final OrderRepository orderRepository;
    16	    private final ProductRepository productRepository;
    17	    private final CustomerRepository customerRepository;
    18	    private final NotificationRepository notificationRepository;
    19	    private final CheckoutService checkoutService;
    20	
    21	    public OrderService(Database database,
    22	                       OrderRepository orderRepository,
    23	                       ProductRepository productRepository,
    24	                       CustomerRepository customerRepository,
    25	                       NotificationRepository notificationRepository,
    26	                       CheckoutService checkoutService) {
    27	        this.database = database;
    28	        this.orderRepository = orderRepository;
    29	        this.productRepository = productRepository;
    30	        this.customerRepository = customerRepository;
    31	        this.notificationRepository = notificationRepository;
    32	        this.checkoutService = checkoutService;
    33	    }
    34	
    35	    public Order createOrder(CheckoutRequest request) {
    36	        try (Connection conn = database.getConnection()) {
    37	            conn.setAutoCommit(false);
    38	            try {
    39	                CheckoutSummary summary = checkoutService.calculateSummary(request, conn);
    40	
    41	                customerRepository.create(request.getCustomer().getCpf(), request.getCustomer().getEmail(), conn);
    42	
    43	                Order order = new Order();
    44	                order.setId(UUID.randomUUID().toString());
    45	                order.setCustomerCpf(request.getCustomer().getCpf());
    46	                order.setCustomerEmail(request.getCustomer().getEmail());
    47	                order.setItems(new ArrayList<>(request.getItems()));
    48	                order.setZipCode(request.getZipCode());
    49	                order.setRegion(request.getRegion());
    50	                order.setShippingMethod(request.getShippingMethod());
    51	                order.setCoupon(request.getCoupon());
    52	                order.setPaymentMethod(request.getPaymentMethod());
    53	                order.setClubTier(request.getClubTier());
    54	                order.setStatus(OrderStatus.AWAITING_PAYMENT);
    55	                order.setCreatedAt(Instant.now());
    56	                order.setSummary(summary);
    57	
    58	                orderRepository.save(order, conn);
    59	
    60	                conn.commit();
    61	                return order;
    62	            } catch (ApiException e) {
    63	                conn.rollback();
    64	                throw e;
    65	            } catch (Exception e) {
    66	                conn.rollback();
    67	                throw new RuntimeException("Failed to create order", e);
    68	            }
    69	        } catch (SQLException e) {
    70	            throw new RuntimeException("Database connection failed", e);
    71	        }
    72	    }
    73	
    74	    public Order getOrder(String orderId) {
    75	        return orderRepository.findById(orderId)
    76	            .orElseThrow(() -> new ApiException("ORDER_NOT_FOUND", 404));
    77	    }
    78	
    79	    public Order processPayment(String orderId, String transactionId, Instant paidAt) {
    80	        try (Connection conn = database.getConnection()) {
    81	            conn.setAutoCommit(false);
    82	            try {
    83	                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
    84	                if (existingOrder.isEmpty()) {
    85	                    conn.rollback();
    86	                    throw new ApiException("ORDER_NOT_FOUND", 404);
    87	                }
    88	
    89	                Order order = existingOrder.get();
    90	
    91	                if (transactionId == null || transactionId.isEmpty() || paidAt == null) {
    92	                    conn.rollback();
    93	                    throw new ApiException("INVALID_ORDER", 422);
    94	                }
    95	
    96	                boolean isNewTransaction = orderRepository.recordPaymentTransaction(orderId, transactionId, paidAt, conn);
    97	
    98	                if (!isNewTransaction) {
    99	                    conn.rollback();
   100	                    return order;
   101	                }
   102	
   103	                if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
   104	                    conn.rollback();
   105	                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
   106	                }
   107	
   108	                Duration elapsed = Duration.between(order.getCreatedAt(), paidAt);
   109	                if (elapsed.compareTo(Duration.ofHours(48)) > 0) {
   110	                    orderRepository.updateStatus(orderId, OrderStatus.CANCELLED, conn);
   111	                    order.setStatus(OrderStatus.CANCELLED);
   112	                    notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId, conn);
   113	                    conn.commit();
   114	                    throw new ApiException("ORDER_EXPIRED", 409);
   115	                }
   116	
   117	                Map<String, Integer> skuQuantities = new HashMap<>();
   118	                for (OrderItem item : order.getItems()) {
   119	                    skuQuantities.put(item.getSku(), item.getQuantity());
   120	                }
   121	
   122	                try {
   123	                    productRepository.decreaseStock(skuQuantities, conn);
   124	                } catch (SQLException e) {
   125	                    if (e.getMessage().equals("INSUFFICIENT_STOCK")) {
   126	                        orderRepository.updateStatus(orderId, OrderStatus.CANCELLED, conn);
   127	                        order.setStatus(OrderStatus.CANCELLED);
   128	                        notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId, conn);
   129	                        conn.commit();
   130	                        throw new ApiException("INSUFFICIENT_STOCK", 409);
   131	                    }
   132	                    throw e;
   133	                }
   134	
   135	                if (order.getSummary().getNextPurchaseCredit().compareTo(java.math.BigDecimal.ZERO) > 0) {
   136	                    customerRepository.addCredit(order.getCustomerCpf(), order.getSummary().getNextPurchaseCredit(), conn);
   137	                }
   138	
   139	                orderRepository.updateStatus(orderId, OrderStatus.PAID, conn);
   140	                orderRepository.updatePaymentTransaction(orderId, transactionId, conn);
   141	                order.setStatus(OrderStatus.PAID);
   142	                order.setPaymentTransactionId(transactionId);
   143	
   144	                notificationRepository.create(order.getCustomerCpf(), NotificationType.PAYMENT_APPROVED, orderId, conn);
   145	
   146	                conn.commit();
   147	                return order;
   148	            } catch (ApiException e) {
   149	                conn.rollback();
   150	                throw e;
   151	            } catch (Exception e) {
   152	                conn.rollback();
   153	                throw new RuntimeException("Failed to process payment", e);
   154	            }
   155	        } catch (SQLException e) {
   156	            throw new RuntimeException("Database connection failed", e);
   157	        }
   158	    }
   159	
   160	    public Order shipOrder(String orderId, String trackingCode) {
   161	        try (Connection conn = database.getConnection()) {
   162	            conn.setAutoCommit(false);
   163	            try {
   164	                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
   165	                if (existingOrder.isEmpty()) {
   166	                    conn.rollback();
   167	                    throw new ApiException("ORDER_NOT_FOUND", 404);
   168	                }
   169	
   170	                Order order = existingOrder.get();
   171	
   172	                if (trackingCode == null || trackingCode.isEmpty()) {
   173	                    conn.rollback();
   174	                    throw new ApiException("INVALID_ORDER", 422);
   175	                }
   176	
   177	                if (order.getStatus() != OrderStatus.PAID) {
   178	                    conn.rollback();
   179	                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
   180	                }
   181	
   182	                orderRepository.updateStatus(orderId, OrderStatus.SHIPPED, conn);
   183	                orderRepository.updateTrackingCode(orderId, trackingCode, conn);
   184	                order.setStatus(OrderStatus.SHIPPED);
   185	                order.setTrackingCode(trackingCode);
   186	
   187	                notificationRepository.create(order.getCustomerCpf(), NotificationType.ORDER_SHIPPED, orderId, conn);
   188	
   189	                conn.commit();
   190	                return order;
   191	            } catch (ApiException e) {
   192	                conn.rollback();
   193	                throw e;
   194	            } catch (Exception e) {
   195	                conn.rollback();
   196	                throw new RuntimeException("Failed to ship order", e);
   197	            }
   198	        } catch (SQLException e) {
   199	            throw new RuntimeException("Database connection failed", e);
   200	        }
   201	    }
   202	
   203	    public Order deliverOrder(String orderId) {
   204	        try (Connection conn = database.getConnection()) {
   205	            conn.setAutoCommit(false);
   206	            try {
   207	                Optional<Order> existingOrder = orderRepository.findByIdForUpdate(orderId, conn);
   208	                if (existingOrder.isEmpty()) {
   209	                    conn.rollback();
   210	                    throw new ApiException("ORDER_NOT_FOUND", 404);
   211	                }
   212	
   213	                Order order = existingOrder.get();
   214	
   215	                if (order.getStatus() != OrderStatus.SHIPPED) {
   216	                    conn.rollback();
   217	                    throw new ApiException("OPERATION_NOT_ALLOWED", 409);
   218	                }
   219	
   220	                orderRepository.updateStatus(orderId, OrderStatus.DELIVERED, conn);
   221	                order.setStatus(OrderStatus.DELIVERED);
   222	
   223	                conn.commit();
   224	                return order;
   225	            } catch (ApiException e) {
   226	                conn.rollback();
   227	                throw e;
   228	            } catch (Exception e) {
   229	                conn.rollback();
   230	                throw new RuntimeException("Failed to deliver order", e);
